arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
*Username*) echo "x-access-token" ;;
*Password*) echo "$GITHUB_TOKEN" ;;
*) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh
GIT_ASKPASS=/tmp/askpass.sh git -C /tmp/joey-worktree push origin HEAD:refs/heads/friend/joey
